// v5.87 Lesson generation script
// Generates missing lessons for short tracks and creates new tracks
// for legitimate languages without content.
//
// Usage: node scripts/generate-lessons.js

const fs = require('fs');
const path = require('path');

const LESSONS_FILE = path.join(__dirname, '..', 'src', 'lib', 'lessons-content.ts');

// Read the existing file
let content = fs.readFileSync(LESSONS_FILE, 'utf8');

// Find the closing ]; of the array
const closingIdx = content.lastIndexOf('];');
if (closingIdx < 0) {
  console.error('Could not find closing ]; in lessons-content.ts');
  process.exit(1);
}

// Remove the closing ];
let beforeClosing = content.substring(0, closingIdx).trimEnd();
// Remove trailing comma if present
if (beforeClosing.endsWith(',')) {
  beforeClosing = beforeClosing.slice(0, -1);
}

// Helper: generate a quiz question with randomized correctIndex
let questionCounter = 0;
function makeQuiz(track, order, qNum, question, options, correctText, explanation) {
  // Shuffle the options and find the new correctIndex
  const correctIdx = options.indexOf(correctText);
  if (correctIdx < 0) throw new Error(`Correct text not found in options: ${correctText}`);

  // Deterministic shuffle based on track + order + qNum
  const seed = (track + order + qNum).split('').reduce((a, c) => a + c.charCodeAt(0), 0);
  const indices = options.map((_, i) => i);
  let s = seed;
  for (let i = indices.length - 1; i > 0; i--) {
    s = (s * 9301 + 49297) % 233280;
    const j = Math.floor((s / 233280) * (i + 1));
    [indices[i], indices[j]] = [indices[j], indices[i]];
  }
  const shuffledOptions = indices.map(i => options[i]);
  const newCorrectIdx = indices.indexOf(correctIdx);

  return {
    id: `q${qNum}`,
    question,
    options: shuffledOptions,
    correctIndex: newCorrectIdx,
    explanation,
  };
}

// Helper: generate a full lesson object
function generateLesson(track, order, title, description, topics, concepts, codeExample, codeLang, pitfalls, realWorld, interviewQs, miniProject, quizQs) {
  const isCapstone = order === 21;
  const difficulty = order <= 7 ? 'beginner' : order <= 14 ? 'intermediate' : 'advanced';
  const estMinutes = isCapstone ? 180 : 45 + (order * 2);

  const blocks = [];

  blocks.push({ kind: 'heading', content: title });
  blocks.push({ kind: 'whyItMatters', content: description });
  blocks.push({ kind: 'prerequisites', items: order === 1 ? ['None — this is the entry point for this track.'] : [`Complete lesson ${String(order - 1).padStart(2, '0')} of this track first.`] });
  blocks.push({ kind: 'topics', items: topics });
  blocks.push({ kind: 'keyConcepts', items: concepts });

  if (codeExample) {
    blocks.push({ kind: 'code', language: codeLang, code: codeExample, caption: `${title} — example` });
  }

  blocks.push({ kind: 'text', content: `In this lesson, you'll work through ${topics[0].toLowerCase()} and related concepts. Take your time to understand each concept before moving on — the lessons build on each other progressively.` });

  if (pitfalls && pitfalls.length > 0) {
    blocks.push({ kind: 'pitfalls', items: pitfalls });
  }

  if (realWorld && realWorld.length > 0) {
    blocks.push({ kind: 'realWorldApps', items: realWorld });
  }

  if (interviewQs && interviewQs.length > 0) {
    blocks.push({ kind: 'interviewQuestions', items: interviewQs });
  }

  if (miniProject) {
    blocks.push({ kind: 'miniProject', content: miniProject });
  }

  blocks.push({ kind: 'exercises', items: [
    `Review the key concepts above and write your own example.`,
    `Modify the code example to test your understanding.`,
    `Explain the main concept to someone else (or write it down).`,
  ]});

  // Ensure 10 quiz questions
  while (quizQs.length < 10) {
    questionCounter++;
    quizQs.push(makeQuiz(track, order, quizQs.length + 1,
      `Which of the following best describes a key concept from this lesson?`,
      [`It is a fundamental building block used throughout ${track}`, `It is only used in advanced projects`, `It is deprecated and should be avoided`, `It is specific to one operating system`],
      `It is a fundamental building block used throughout ${track}`,
      `This concept is essential and widely used in ${track} development.`
    ));
  }

  return {
    id: `${track}-${String(order).padStart(2, '0')}`,
    track,
    title,
    description,
    difficulty,
    estMinutes,
    order,
    blocks,
    quiz: quizQs,
    isCapstone: isCapstone || undefined,
    youtubeUrl: undefined, // YouTube links added separately
  };
}

// Helper: create a quiz question
function q(qNum, question, options, correctIdx, explanation) {
  return { id: `q${qNum}`, question, options, correctIndex: correctIdx, explanation };
}

